SET default_transaction_read_only = on;
-- #644 forward step 1: closes for 631 tickers (forward entrant baskets + SPY).
-- Window 2026-08-01 (>=30 trading days before first as_of 2026-09-18) .. 2026-11-27.
-- Run: psql -A -F ',' -f closes.sql > closes.out   (first line = header: ticker,trade_date,close; old _644_closes.csv had none)
SELECT ticker, trade_date, close
FROM mi_daily_closes
WHERE trade_date BETWEEN '2026-08-01' AND '2026-11-27'
  AND ticker = ANY(ARRAY['A','ABT','ABTC','ACHC','ACLS','ACM','ACMR','ACN','ADP','ADPT','ADSK','ADT','AEHR','AEIS','AEO','AER','AGL','AGX','AGYS','AI','AJG','ALC','ALGN','ALIT','ALL','ALLE','ALNT','ALRM','AMAT','AMGN','AMPL','ANF','ANRO','AON','AOS','APA','APD','APG','APLD','APOG','APP','APPF','APPN','AR','ARGX','ARHS','ARLO','ARXS','ASAN','ASC','ASML','ASO','ASST','ASX','ATAT','ATEC','ATEN','ATI','ATO','ATRC','AVTR','AXGN','AXTI','AZN','AZTA','BAX','BBIO','BBNX','BBWI','BDX','BE','BEAM','BIIB','BILL','BIRK','BJ','BJRI','BKE','BKR','BL','BLKB','BLMN','BMRN','BMY','BNTX','BOBS','BOOT','BOX','BP','BRKR','BRO','BSP','BSX','BTDR','BTSG','BURL','BWIN','CAI','CAKE','CAMT','CART','CBOE','CBRL','CBZ','CCC','CCEP','CCL','CDNA','CDNS','CDRE','CE','CEG','CELH','CGON','CHH','CHKP','CHRD','CHTR','CHWY','CLF','CLSK','CMBT','CMCSA','CMG','CNMD','CNQ','CNX','CNXC','COAG','COHU','COIN','COKE','COLM','COP','COST','CPRI','CRAI','CRGY','CRI','CRK','CRL','CRM','CROX','CRSP','CRWD','CTSH','CUBE','CVE','CVI','CVLT','CVX','CWST','DAVE','DBX','DDOG','DFIN','DG','DGX','DHR','DHT','DIN','DINO','DK','DKS','DLTR','DNTH','DOCU','DOW','DPZ','DRI','DSGX','DT','DUOL','DV','DVN','DXC','DXCM','E','EAT','EBAY','EC','ECO','EFOR','ELF','EMBJ','ENOV','ENTG','EOG','EPAM','EPD','EQNR','EQT','EROC','ESTC','ETN','ETSY','EVER','EW','EXE','EXEL','EXLS','EXPO','EXR','FA','FANG','FCN','FDS','FEIM','FER','FFIV','FIGS','FIVE','FIVN','FIZZ','FORM','FPS','FRO','FROG','FRPT','FRSH','FSLY','FTI','FTNT','FTRE','FWONA','FWONK','FWRG','G','GAP','GATX','GCT','GDDY','GDYN','GEHC','GENB','GH','GIB','GIII','GILD','GKOS','GLBE','GLIBK','GLOB','GLXY','GMAB','GME','GNRC','GRAL','GRDN','GVA','GWRE','H','HAE','HAFN','HAL','HALO','HAS','HAYW','HCI','HDB','HELE','HESM','HLT','HNI','HP','HRI','HTFL','HTHT','HURN','HUT','HWKN','IBM','IBN','IBTA','ICFI','ICLR','ICUI','IDT','IDXX','IHG','ILMN','IMO','IMVT','INFY','INSM','INSP','INSW','INTA','INTC','INTR','IOND','IQV','IRON','ISRG','ITGR','ITUB','J','JBIO','JKHY','JMKE','KD','KDP','KEYS